import{_ as r,o as a,c as i,a2 as d}from"./chunks/framework.CqpfiAoK.js";const u=JSON.parse('{"title":"Происхождение и сущность тёмных замещающих сущностей","description":"","frontmatter":{},"headers":[],"relativePath":"ru/57-黑暗置换体起源与本质.md","filePath":"ru/57-黑暗置换体起源与本质.md"}'),l={name:"ru/57-黑暗置换体起源与本质.md"};function o(e,t,n,h,s,g){return a(),i("div",null,[...t[0]||(t[0]=[d('<h1 id="происхождение-и-сущность-темных-замещающих-сущностеи" tabindex="-1">Происхождение и сущность тёмных замещающих сущностей <a class="header-anchor" href="#происхождение-и-сущность-темных-замещающих-сущностеи" aria-label="Permalink to &quot;Происхождение и сущность тёмных замещающих сущностей&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Позиция</th><th>Содержание</th></tr></thead><tbody><tr><td>№ документа</td><td>57</td></tr><tr><td>Модуль</td><td>Расы и формы жизни</td></tr><tr><td>Ключевые слова</td><td>Тёмная замещающая сущность, Бездонная Энергия, сосуществование двух душ, происхождение и сущность, симбиотическая угроза</td></tr></tbody></table><h2 id="i-определение-темных-замещающих-сущностеи" tabindex="-1">I. Определение тёмных замещающих сущностей <a class="header-anchor" href="#i-определение-темных-замещающих-сущностеи" aria-label="Permalink to &quot;I. Определение тёмных замещающих сущностей&quot;">​</a></h2><p>В Изначальной Вселенной Ваньлин Хэнмао (Вселенная Хэнъюань) «тёмная замещающая сущность» — это особая форма жизни, образующаяся после того, как живое существо подверглось разъеданию Бездонной Энергией или другой тёмной энергией, в результате чего исходная душа была частично или полностью замещена тёмной энергией, формируя особую форму жизни, в которой сосуществуют исходная душа и тёмная душа. Тёмная замещающая сущность — это не просто «живое существо, заражённое тёмной энергией», а существо, прошедшее замещение и перестройку на уровне души. Её сущность в том, что в одном теле находятся две взаимно конфликтующие и взаимно зависимые души — исходная хозяйская душа и тёмная замещающая душа.</p><p>Тёмные замещающие сущности — одна из самых сложных проблем жизненной этики и управления безопасностью, с которыми сталкивается Симбиотическая Цивилизация Якоря. Они отличаются и от аномальной жизни (аномальная жизнь — это совершенно новая неизвестная жизнь, а тёмные замещающие сущности — продукт модификации известной жизни), и от обычных заражённых энергией существ (у обычных заражённых разъедено только тело, а души тёмных замещающих сущностей уже замещены). Их особенность в том, что они вовлекают конфликт прав двух душ, этические дилеммы и риски безопасности, требуя специальных правил идентификации, этики и обращения.</p><h2 id="ii-происхождение-темных-замещающих-сущностеи" tabindex="-1">II. Происхождение тёмных замещающих сущностей <a class="header-anchor" href="#ii-происхождение-темных-замещающих-сущностеи" aria-label="Permalink to &quot;II. Происхождение тёмных замещающих сущностей&quot;">​</a></h2><p>Возникновение тёмных замещающих сущностей требует специфических условий и процессов. Их происхождение можно проследить до следующих аспектов:</p><h3 id="i-источник-бездоннои-энергии" tabindex="-1">(I) Источник Бездонной Энергии <a class="header-anchor" href="#i-источник-бездоннои-энергии" aria-label="Permalink to &quot;(I) Источник Бездонной Энергии&quot;">​</a></h3><p>Бездонная Энергия — центральный фактор возникновения тёмных замещающих сущностей. Бездонная Энергия происходит из Космической Бездны — самой тёмной области на самом низком уровне Вселенной Хэнъюань, где собирается первобытная тёмная энергия, отвергнутая при рождении вселенной. Бездонная Энергия обладает следующими характеристиками:</p><table tabindex="0"><thead><tr><th>Характеристика</th><th>Описание</th></tr></thead><tbody><tr><td>Эрозивность</td><td>Бездонная Энергия может разъедать тело и душу живых существ, постепенно превращая их в тёмные атрибуты</td></tr><tr><td>Соблазнительность</td><td>Бездонная Энергия может усиливать негативные эмоции и желания живых существ, побуждая их активно принимать тёмную энергию</td></tr><tr><td>Замещаемость</td><td>Достигнув определённой концентрации, Бездонная Энергия может заместить душу живого существа, формируя тёмную замещающую душу</td></tr><tr><td>Инфекционность</td><td>Тёмные замещающие сущности могут передавать Бездонную Энергию другим живым существам через контакт, атаки, вторжение в сознание и т.д.</td></tr><tr><td>Эволюционность</td><td>Бездонная Энергия может эволюционировать вместе с эволюцией хозяина, производя более мощные тёмные способности</td></tr></tbody></table><h3 id="ii-условия-возникновения" tabindex="-1">(II) Условия возникновения <a class="header-anchor" href="#ii-условия-возникновения" aria-label="Permalink to &quot;(II) Условия возникновения&quot;">​</a></h3><p>Возникновение тёмных замещающих сущностей требует одновременного выполнения следующих условий:</p><ol><li><strong>Воздействие Бездонной Энергии</strong> : живое существо подвергается воздействию Бездонной Энергии высокой концентрации или длительно контактирует с Бездонной Энергией низкой концентрации.</li><li><strong>Период уязвимости души</strong> : душа живого существа находится в уязвимом состоянии, например при прорывах культивации, тяжёлых ранениях, крайних эмоциональных колебаниях, психических срывах и т.д.</li><li><strong>Катализ негативных эмоций</strong> : живое существо испытывает сильные негативные эмоции, такие как негодование, страх, жадность, отчаяние и т.д. ; эти эмоции — лучшие катализаторы Бездонной Энергии.</li><li><strong>Активное или пассивное принятие</strong> : живое существо активно принимает тёмную силу под соблазном Бездонной Энергии или пассивно разъедается, когда не в силах сопротивляться.</li><li><strong>Завершение замещения души</strong> : Бездонная Энергия пускает корни в душе и завершает замещение, формируя независимую тёмную замещающую душу.</li></ol><h3 id="iii-пути-возникновения" tabindex="-1">(III) Пути возникновения <a class="header-anchor" href="#iii-пути-возникновения" aria-label="Permalink to &quot;(III) Пути возникновения&quot;">​</a></h3><p>Тёмные замещающие сущности в основном возникают следующими путями:</p><ul><li><strong>Контакт с бездонной областью</strong> : живое существо входит в Космическую Бездну или зону утечки Бездонной Энергии и разъедается Бездонной Энергией высокой концентрации.</li><li><strong>Превращение тёмного культиватора</strong> : культиватор активно практикует тёмные искусства, длительно поглощая Бездонную Энергию, и в конце концов замещается тёмной душой.</li><li><strong>Заражение тёмной замещающей сущностью</strong> : атака существующей тёмной замещающей сущностью или вторжение в сознание, при котором Бездонная Энергия проникает через раны или каналы сознания.</li><li><strong>Проклятия руин и артефактов</strong> : контакт с древними руинами или проклятыми предметами, загрязнёнными Бездонной Энергией, разъедание тёмной энергией, запечатанной в них.</li><li><strong>Аварии экспериментов</strong> : аварии в экспериментах с Бездонной Энергией, при которых персонал разъедается вышедшей из-под контроля Бездонной Энергией.</li><li><strong>Вторжение через плоскостные трещины</strong> : тёмные существа, вторгшиеся из Бездонной Плоскости через плоскостные трещины, напрямую замещают души местных живых существ.</li></ul><h2 id="iii-сущность-темных-замещающих-сущностеи" tabindex="-1">III. Сущность тёмных замещающих сущностей <a class="header-anchor" href="#iii-сущность-темных-замещающих-сущностеи" aria-label="Permalink to &quot;III. Сущность тёмных замещающих сущностей&quot;">​</a></h2><p>Сущность тёмной замещающей сущности — «сущность сосуществования двух душ», со следующими центральными характеристиками:</p><h3 id="i-структура-двух-душ" tabindex="-1">(I) Структура двух душ <a class="header-anchor" href="#i-структура-двух-душ" aria-label="Permalink to &quot;(I) Структура двух душ&quot;">​</a></h3><p>В теле тёмной замещающей сущности находятся две независимые души:</p><table tabindex="0"><thead><tr><th>Душа</th><th>Название</th><th>Характеристики</th></tr></thead><tbody><tr><td>Исходная хозяйская душа</td><td>Душа, изначально принадлежащая хозяину</td><td>Сохраняет воспоминания, личность, сознание и эмоции исходного хозяина, но её сила подавлена тёмной душой</td></tr><tr><td>Замещающая душа</td><td>Тёмная душа, образованная конденсацией Бездонной Энергии</td><td>Обладает независимым сознанием, воспоминаниями и личностью, с мощной силой, склонна к тьме и хищничеству</td></tr></tbody></table><p>Две души разделяют одно тело и борются за контроль над телом. В большинстве случаев тёмная замещающая душа занимает доминирующее положение, а исходная хозяйская душа подавлена в глубинах сознания ; но при определённых условиях (таких как сильная эмоциональная стимуляция, очищение светлой энергией или прорыв воли исходного хозяина) исходная хозяйская душа может временно вернуть контроль над телом.</p><h3 id="ii-конфликт-и-взаимозависимость-душ" tabindex="-1">(II) Конфликт и взаимозависимость душ <a class="header-anchor" href="#ii-конфликт-и-взаимозависимость-душ" aria-label="Permalink to &quot;(II) Конфликт и взаимозависимость душ&quot;">​</a></h3><p>Между двумя душами существует сложная связь конфликта и взаимозависимости:</p><ul><li><strong>Конфликтность</strong> : две души борются за контроль над телом ; исходная хозяйская душа пытается изгнать тёмную душу, чтобы вернуть свободу, а тёмная душа пытается полностью уничтожить исходную хозяйскую душу и полностью овладеть телом.</li><li><strong>Взаимозависимость</strong> : две души разделяют одно тело и одно жизненное начало ; гибель одной может вызвать гибель другой или разрушение тела. Тёмная душа нуждается в исходной хозяйской душе как в «якоре» для поддержания своего существования в материальном мире, а исходная хозяйская душа нуждается в силе тёмной души для поддержания функционирования тела (в случаях глубокого замещения).</li><li><strong>Возможность слияния</strong> : в крайне редких случаях две души могут достичь примирения и осуществить слияние душ, формируя новую душу, обладающую и воспоминаниями исходного хозяина, и тёмной силой.</li></ul><h3 id="iii-характеристики-способностеи" tabindex="-1">(III) Характеристики способностей <a class="header-anchor" href="#iii-характеристики-способностеи" aria-label="Permalink to &quot;(III) Характеристики способностей&quot;">​</a></h3><p>Тёмные замещающие сущности обычно обладают следующими характеристиками способностей:</p><ol><li><strong>Управление тёмной энергией</strong> : могут управлять Бездонной Энергией и энергией тёмных атрибутов, накладывая тёмные заклинания и атаки.</li><li><strong>Усиление тела</strong> : тело усилено Бездонной Энергией, сила, скорость и оборонительная мощь значительно превосходят обычных живых существ.</li><li><strong>Способность регенерации</strong> : обладают мощной способностью регенерации, обычные раны быстро восстанавливаются.</li><li><strong>Способность заражения</strong> : могут передавать Бездонную Энергию другим живым существам через атаки или контакт, создавая новые тёмные замещающие сущности.</li><li><strong>Усиленное восприятие</strong> : обладают чрезвычайно сильным восприятием тёмной энергии, негативных эмоций и жизненной ауры.</li><li><strong>Трансформация формы</strong> : могут превращаться в тёмную форму или форму монстра, дополнительно усиливая боевую мощь.</li><li><strong>Атака души</strong> : могут напрямую атаковать души других живых существ, вызывая травмы души или загрязнение души.</li></ol><h3 id="iv-поведенческие-тенденции" tabindex="-1">(IV) Поведенческие тенденции <a class="header-anchor" href="#iv-поведенческие-тенденции" aria-label="Permalink to &quot;(IV) Поведенческие тенденции&quot;">​</a></h3><p>Поведенческие тенденции тёмной замещающей сущности зависят от того, какая душа занимает доминирующее положение:</p><ul><li><strong>Когда доминирует тёмная душа</strong> : поведение склоняется к разрушению, хищничеству, убийствам и распространению тёмной энергии, с сильной агрессивностью и антисоциальными тенденциями.</li><li><strong>Когда доминирует исходная хозяйская душа</strong> : поведение склоняется к исходной личности и ценностям хозяина, но подвержено влиянию тёмной энергии, эмоции легче колеблются и легче провоцируются.</li><li><strong>Когда две души конфликтуют</strong> : поведение проявляется как хаос и противоречивость, иногда ясность, иногда потеря контроля, представляя опасность и для себя, и для других.</li></ul><h2 id="iv-стадии-развития-темных-замещающих-сущностеи" tabindex="-1">IV. Стадии развития тёмных замещающих сущностей <a class="header-anchor" href="#iv-стадии-развития-темных-замещающих-сущностеи" aria-label="Permalink to &quot;IV. Стадии развития тёмных замещающих сущностей&quot;">​</a></h2><p>От разъедания до полного замещения тёмная замещающая сущность обычно проходит следующие стадии развития:</p><table tabindex="0"><thead><tr><th>Стадия</th><th>Название</th><th>Характеристики</th><th>Обратимость</th></tr></thead><tbody><tr><td>Первая стадия</td><td>Период энергетического разъедания</td><td>Бездонная Энергия начинает разъедать тело, с физическим недомоганием и эмоциональными колебаниями ; душа ещё не замещена</td><td>Полностью обратимо</td></tr><tr><td>Вторая стадия</td><td>Период загрязнения души</td><td>Бездонная Энергия вторгается в душу ; исходная хозяйская душа загрязняется, с изменениями личности и тёмными импульсами</td><td>Большей частью обратимо</td></tr><tr><td>Третья стадия</td><td>Период формирования двух душ</td><td>Формируется тёмная замещающая душа, устанавливается структура сосуществования двух душ, исходная хозяйская душа начинает подавляться</td><td>Частично обратимо</td></tr><tr><td>Четвёртая стадия</td><td>Период тёмного доминирования</td><td>Тёмная душа полностью занимает доминирующее положение, исходная хозяйская душа глубоко подавлена, тело в основном преобразовано тёмной энергией</td><td>Труднообратимо</td></tr><tr><td>Пятая стадия</td><td>Период полного замещения</td><td>Исходная хозяйская душа полностью уничтожена или ассимилирована, тёмная душа полностью контролирует тело, становясь чисто тёмным существованием</td><td>Необратимо</td></tr></tbody></table><p>С первой по третью стадию тёмные замещающие сущности ещё имеют возможность восстановления ; после вступления в четвёртую стадию восстановление крайне затруднено ; на пятой стадии исходный хозяин больше не существует, и сущность можно обрабатывать только как чисто тёмное существование.</p><h2 id="v-отношения-между-темными-замещающими-сущностями-и-симбиотическои-цивилизациеи" tabindex="-1">V. Отношения между тёмными замещающими сущностями и симбиотической цивилизацией <a class="header-anchor" href="#v-отношения-между-темными-замещающими-сущностями-и-симбиотическои-цивилизациеи" aria-label="Permalink to &quot;V. Отношения между тёмными замещающими сущностями и симбиотической цивилизацией&quot;">​</a></h2><p>Тёмные замещающие сущности — серьёзный вызов для Симбиотической Цивилизации Якоря. Их отношения с симбиотической цивилизацией отражаются в следующих аспектах:</p><ol><li><strong>Концептуальный конфликт</strong> : тёмная душа тёмной замещающей сущности склоняется к хищничеству и разрушению, принципиально противостоя концепции «антихищничество, содействие симбиозу» симбиотической цивилизации.</li><li><strong>Угроза безопасности</strong> : тёмные замещающие сущности обладают мощной боевой способностью и способностью заражения, представляя прямую угрозу безопасности симбиотической цивилизации.</li><li><strong>Этическая дилемма</strong> : исходная хозяйская душа внутри тёмной замещающей сущности — законный член симбиотической цивилизации, и её основные права должны защищаться ; однако опасность тёмной души требует мер контроля. Как сбалансировать эти два аспекта — глубокая этическая дилемма.</li><li><strong>Вызов управлению</strong> : идентификация, изоляция, лечение и обращение с тёмными замещающими сущностями требуют специальных институтов и ресурсов, предъявляя высокие требования к способности управления симбиотической цивилизации.</li><li><strong>Возможность преобразования</strong> : пока исходная хозяйская душа ещё существует, посредством очищения, слияния, разделения и других средств некоторые тёмные замещающие сущности могут быть спасены и заново включены в симбиотическую систему.</li></ol><h2 id="заключение" tabindex="-1">Заключение <a class="header-anchor" href="#заключение" aria-label="Permalink to &quot;Заключение&quot;">​</a></h2><p>Тёмные замещающие сущности — особые существования, порождённые переплетением Бездонной Энергии и душ живых существ. Их сущность — противоречивое единство сосуществования двух душ. Они одновременно и угроза безопасности для симбиотической цивилизации, и испытание её этической глубины и способности управления. Понимание происхождения и сущности тёмных замещающих сущностей — предпосылка и основа для разработки Этики Двойной Души (см. <em>58-双魂伦理准则</em>) и правил обращения с четырьмя ветвями (см. <em>59-黑暗置换体四类分支处置</em>).</p><h2 id="связанные-документы" tabindex="-1">Связанные документы <a class="header-anchor" href="#связанные-документы" aria-label="Permalink to &quot;Связанные документы&quot;">​</a></h2><ul><li>58-双魂伦理准则 (Этика Двойной Души)</li><li>59-黑暗置换体四类分支处置 (Обращение с четырьмя ветвями тёмных замещающих сущностей)</li><li>55-奇异能量分类与特性 (Классификация и характеристики аномальной энергии)</li><li>53-奇特生命识别标准 (Стандарты идентификации аномальной жизни)</li></ul>',42)])])}const c=r(l,[["render",o]]);export{u as __pageData,c as default};
